# right_to_wrong case
right_orig={(json.loads(l)['qid'],json.loads(l)['sample']) for l in open('/work/gen_9_original.jsonl') if json.loads(l)['correct']}
wrong_edit={(r['qid'],r['sample']) for r in rows if not r['correct']}
print('lost:', right_orig & wrong_edit)

